export interface AppConfig {
  port: number;
  host: string;
  revision: string;
}

const REVISION_REGEX = /^[A-Za-z0-9._-]+$/;

export function loadConfig(): AppConfig {
  const port = parseInt(process.env.PORT || '3000', 10);
  const host = process.env.HOST || '0.0.0.0';

  const rawRevision = process.env.APP_REVISION || '0.1.0';
  const revision = REVISION_REGEX.test(rawRevision) ? rawRevision : '0.1.0';

  return {
    port: Number.isNaN(port) ? 3000 : port,
    host,
    revision,
  };
}

export const config = loadConfig();

import type { FastifyPluginAsync } from 'fastify';
import { renderBaselineHtml } from '../views/baseline.js';
import { loadConfig } from '../config/index.js';

export const baselineRoutes: FastifyPluginAsync = async (fastify) => {
  const currentConfig = loadConfig();

  fastify.get('/health', async (_request, reply) => {
    return reply
      .code(200)
      .type('application/json')
      .send({ status: 'ok' });
  });

  fastify.get('/revision', async (_request, reply) => {
    return reply
      .code(200)
      .type('application/json')
      .send({ revision: currentConfig.revision });
  });

  fastify.get('/', async (_request, reply) => {
    const html = renderBaselineHtml(currentConfig.revision);
    return reply
      .code(200)
      .type('text/html')
      .send(html);
  });
};

import type { FastifyInstance } from 'fastify';

export function registerNotFoundHandler(fastify: FastifyInstance): void {
  fastify.setNotFoundHandler((_request, reply) => {
    reply
      .code(404)
      .type('application/json')
      .send({
        error: 'Not Found',
        message: 'Route not found',
        statusCode: 404,
      });
  });
}

import Fastify, { type FastifyInstance } from 'fastify';
import { baselineRoutes } from './routes/baseline.js';
import { registerNotFoundHandler } from './routes/not-found.js';

export function createApp(): FastifyInstance {
  const app = Fastify({
    logger: false,
    disableRequestLogging: true,
  });

  registerNotFoundHandler(app);
  app.register(baselineRoutes);

  return app;
}

import { createApp } from './src/app.js';
import { loadConfig } from './src/config/index.js';

export async function startServer(): Promise<void> {
  const config = loadConfig();
  const app = createApp();

  try {
    const address = await app.listen({
      port: config.port,
      host: config.host,
    });
    console.log(`Server listening on ${address}`);
  } catch (err) {
    console.error('Failed to start server:', err);
    process.exit(1);
  }

  const signals: NodeJS.Signals[] = ['SIGINT', 'SIGTERM'];
  for (const signal of signals) {
    process.on(signal, async () => {
      console.log(`Received ${signal}, closing server...`);
      await app.close();
      process.exit(0);
    });
  }
}

// Start server when executed directly
