import { JSDOM, VirtualConsole } from 'jsdom';
import axe from 'axe-core';
import { createApp } from '../src/app.js';

async function runAccessibilityCheck(): Promise<void> {
  console.log('--- Running WCAG 2.2 AA Accessibility Verification ---');

  const app = createApp();
  await app.ready();

  const response = await app.inject({
    method: 'GET',
    url: '/',
  });

  await app.close();

  if (response.statusCode !== 200) {
    console.error(`FAIL: Served document GET / returned status ${response.statusCode}, expected 200`);
    process.exit(1);
  }

  const contentType = response.headers['content-type'] || '';
  if (!contentType.startsWith('text/html')) {
    console.error(`FAIL: Served document GET / returned Content-Type "${contentType}", expected text/html`);
    process.exit(1);
  }

  const html = response.body;
  if (!html || html.trim().length === 0) {
    console.error('FAIL: Served document GET / returned empty body');
    process.exit(1);
  }

  const virtualConsole = new VirtualConsole();
  // Filter out the canvas warning from jsdom in headless environments
  virtualConsole.sendTo(console, { omitJSDOMErrors: true });

  const dom = new JSDOM(html, {
    runScripts: 'dangerously',
    virtualConsole,
  });

  // Inject axe-core into the jsdom environment
  dom.window.eval(axe.source);

  const axeInstance = (dom.window as unknown as { axe: typeof axe }).axe;

  const results = await axeInstance.run(dom.window.document, {
    runOnly: {
      type: 'tag',
      values: ['wcag2a', 'wcag2aa', 'wcag21a', 'wcag21aa', 'wcag22aa'],
    },
    rules: {
      'document-title': { enabled: true },
      'html-has-lang': { enabled: true },
      'landmark-one-main': { enabled: true },
      'landmark-main-is-top-level': { enabled: true },
      'landmark-no-duplicate-main': { enabled: true },
      'region': { enabled: true },
      'color-contrast': { enabled: false },
    },
  });

  console.log(`Passed rules (${results.passes.length}):`, results.passes.map((p) => p.id).join(', '));

  // Zero-target guard: fail closed if no rules evaluated
  if (!results.passes || results.passes.length === 0) {
    console.error('FAIL: Zero-target guard tripped: No accessibility rules evaluated against served HTML');
    process.exit(1);
  }

  // Verify mandatory rules were explicitly evaluated and passed
  const passedRuleIds = new Set(results.passes.map((p) => p.id));
  const mandatoryRules = ['document-title', 'html-has-lang', 'landmark-main-is-top-level'];
  for (const rule of mandatoryRules) {
    if (!passedRuleIds.has(rule)) {
      console.error(`FAIL: Mandatory accessibility rule "${rule}" did not evaluate or pass`);
      process.exit(1);
    }
  }

  // Violations threshold: must be zero
  if (results.violations.length > 0) {
    console.error(`FAIL: Accessibility check failed with ${results.violations.length} violation(s):`);
    for (const v of results.violations) {
      console.error(`- [${v.id}] ${v.help} (${v.nodes.length} occurrences)`);
    }
    process.exit(1);
  }

  console.log('SUCCESS: Accessibility check passed with 0 violations and all mandatory rules verified.');
}

runAccessibilityCheck().catch((err) => {
  console.error('Unhandled error during accessibility check:', err);
  process.exit(1);
});

import { JSDOM } from 'jsdom';
import { createApp } from '../src/app.js';

async function runSecretHygieneCheck(): Promise<void> {
  console.log('--- Running Deterministic Secret Hygiene Verification ---');

  // Step 1: Sanitized environment + canary injection
  const secretSuffixRegex = /(_KEY|_SECRET|_TOKEN|_PASSWORD|_API_KEY|_CREDENTIAL)$/i;
  for (const key of Object.keys(process.env)) {
    if (secretSuffixRegex.test(key)) {
      delete process.env[key];
    }
  }

  const CANARY_API_KEY = 'a1b2c3d4e5f60718293a4b5c6d7e8f9012345678';
  const CANARY_SECRET = 'fedcba9876543210fedcba9876543210fedcba98';

  process.env.PANCHEW_CANARY_API_KEY = CANARY_API_KEY;
  process.env.PANCHEW_CANARY_SECRET = CANARY_SECRET;

  const app = createApp();
  await app.ready();

  const healthRes = await app.inject({ method: 'GET', url: '/health' });
  const revisionRes = await app.inject({ method: 'GET', url: '/revision' });
  const rootRes = await app.inject({ method: 'GET', url: '/' });

  await app.close();

  let violations = 0;

  // Step 2: Body single-key object checks
  try {
    const healthJson = JSON.parse(healthRes.body);
    const healthKeys = Object.keys(healthJson);
    if (healthKeys.length !== 1 || healthJson.status !== 'ok') {
      console.error(`FAIL: /health body is not exactly {"status":"ok"}: ${healthRes.body}`);
      violations++;
    }
  } catch (err) {
    console.error('FAIL: /health body is not valid JSON:', err);
    violations++;
  }

  let revisionVal = '';
  try {
    const revisionJson = JSON.parse(revisionRes.body);
    const revisionKeys = Object.keys(revisionJson);
    if (revisionKeys.length !== 1 || typeof revisionJson.revision !== 'string') {
      console.error(`FAIL: /revision body is not single-key {"revision":"<label>"}: ${revisionRes.body}`);
      violations++;
    } else {
      revisionVal = revisionJson.revision;
    }
  } catch (err) {
    console.error('FAIL: /revision body is not valid JSON:', err);
    violations++;
  }

  // Step 3: No canaries or filesystem paths across all three responses
  const responses = [
    { route: '/health', body: healthRes.body },
    { route: '/revision', body: revisionRes.body },
    { route: '/', body: rootRes.body },
  ];

  // Spec patterns:
  // - Unix absolute path (two or more segments), leading / not immediately preceded by <:
  //   /(?<!<)\/([A-Za-z0-9_.-]+)(\/[A-Za-z0-9_.-]+)+/
  // - Windows drive path: \b[A-Za-z]:[\\/]
  // - Home path: ~/([A-Za-z0-9_.-]+/)*[A-Za-z0-9_.-]+
  const unixPathRegex = /(?<!<)\/([A-Za-z0-9_.-]+)(\/[A-Za-z0-9_.-]+)+/g;
  const winPathRegex = /\b[A-Za-z]:[\\/]/g;
  const homePathRegex = /~\/([A-Za-z0-9_.-]+\/)*[A-Za-z0-9_.-]+/g;

  for (const { route, body } of responses) {
    // Canary checks
    if (body.includes(CANARY_API_KEY)) {
      console.error(`FAIL: Canary PANCHEW_CANARY_API_KEY leaked in ${route}`);
      violations++;
    }
    if (body.includes(CANARY_SECRET)) {
      console.error(`FAIL: Canary PANCHEW_CANARY_SECRET leaked in ${route}`);
      violations++;
    }

    // Path pattern checks
    const unixMatches = body.match(unixPathRegex);
    if (unixMatches && unixMatches.length > 0) {
      console.error(`FAIL: Unix path pattern detected in ${route}: ${unixMatches.join(', ')}`);
      violations++;
    }

    const winMatches = body.match(winPathRegex);
    if (winMatches && winMatches.length > 0) {
      console.error(`FAIL: Windows path pattern detected in ${route}: ${winMatches.join(', ')}`);
      violations++;
    }

    const homeMatches = body.match(homePathRegex);
    if (homeMatches && homeMatches.length > 0) {
      console.error(`FAIL: Home path pattern detected in ${route}: ${homeMatches.join(', ')}`);
      violations++;
    }
  }

  // Step 4: Status and revision value patterns and GET / visible text
  const allowedValueRegex = /^[A-Za-z0-9._-]+$/;
  if (!allowedValueRegex.test('ok')) {
    console.error('FAIL: Status value "ok" does not match ^[A-Za-z0-9._-]+$');
    violations++;
  }

  if (!allowedValueRegex.test(revisionVal)) {
    console.error(`FAIL: Revision value "${revisionVal}" does not match ^[A-Za-z0-9._-]+$`);
    violations++;
  }

  const dom = new JSDOM(rootRes.body);
  const title = dom.window.document.title;
  const bodyText = dom.window.document.body.textContent || '';
  const visibleWords = bodyText.trim().split(/\s+/).filter(Boolean);

  const allowedTokens = new Set([title, revisionVal]);
  for (const word of visibleWords) {
    if (!allowedTokens.has(word)) {
      console.error(`FAIL: Unexpected visible text token "${word}" in GET / body. Allowed tokens:`, Array.from(allowedTokens));
      violations++;
    }
  }

  if (violations > 0) {
    console.error(`FAIL: Secret hygiene check failed with ${violations} rule violation(s).`);
    process.exit(1);
  }

  console.log('SUCCESS: Secret hygiene check passed with 0 violations.');
}

runSecretHygieneCheck().catch((err) => {
  console.error('Unhandled error in secret hygiene check:', err);
  process.exit(1);
});

import { spawn, type ChildProcess } from 'node:child_process';
import http from 'node:http';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import autocannon from 'autocannon';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

interface RouteSpec {
  route: string;
  expectedStatus: number;
  expectedContentType: string;
}

const ROUTES: RouteSpec[] = [
  { route: '/health', expectedStatus: 200, expectedContentType: 'application/json' },
  { route: '/revision', expectedStatus: 200, expectedContentType: 'application/json' },
  { route: '/', expectedStatus: 200, expectedContentType: 'text/html' },
];

const COLD_START_TIMEOUT_MS = 10000;
const COLD_START_CADENCE_MS = 100;
const REQUEST_TIMEOUT_MS = 5000;
const WARMUP_REQUESTS_PER_ROUTE = 100;
const SUSTAINED_REQUESTS_PER_ROUTE = 1000;
const CONCURRENT_CONNECTIONS = 10;
const P95_THRESHOLD_MS = 100;

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function probeHealth(port: number): Promise<boolean> {
  return new Promise((resolve) => {
    const req = http.get(
      {
        host: '127.0.0.1',
        port,
        path: '/health',
        timeout: 500,
      },
      (res) => {
        resolve(res.statusCode === 200);
      }
    );
    req.on('error', () => resolve(false));
    req.on('timeout', () => {
      req.destroy();
      resolve(false);
    });
  });
}

function validateSingleRequest(
  port: number,
  routeSpec: RouteSpec
): Promise<{ ok: boolean; error?: string }> {
  return new Promise((resolve) => {
    const req = http.get(
      {
        host: '127.0.0.1',
        port,
        path: routeSpec.route,
        timeout: REQUEST_TIMEOUT_MS,
      },
      (res) => {
        const contentType = res.headers['content-type'] || '';
        const statusOk = res.statusCode === routeSpec.expectedStatus;
        const ctOk = contentType.startsWith(routeSpec.expectedContentType);

        // Consume data
        res.on('data', () => {});
        res.on('end', () => {
          if (!statusOk) {
            resolve({ ok: false, error: `Expected status ${routeSpec.expectedStatus}, got ${res.statusCode}` });
          } else if (!ctOk) {
            resolve({ ok: false, error: `Expected Content-Type ${routeSpec.expectedContentType}, got ${contentType}` });
          } else {
            resolve({ ok: true });
          }
        });
      }
    );

    req.on('error', (err) => resolve({ ok: false, error: err.message }));
    req.on('timeout', () => {
      req.destroy();
      resolve({ ok: false, error: `Request timed out after ${REQUEST_TIMEOUT_MS}ms` });
    });
  });
}

async function runPerformanceBenchmark(): Promise<void> {
  console.log('====================================================');
  console.log('   P1-M1-E1.1 Executable Performance Benchmark');
  console.log('====================================================\n');

  const hostInfo = {
    runtime: `Node.js ${process.version}`,
    os: `${os.type()} ${os.release()} (${os.platform()})`,
    arch: os.arch(),
    cpus: os.cpus().length,
  };

  console.log('Host Environment:');
  console.log(`- Runtime:      ${hostInfo.runtime}`);
  console.log(`- OS:           ${hostInfo.os}`);
  console.log(`- Architecture: ${hostInfo.arch}`);
  console.log(`- CPU Cores:    ${hostInfo.cpus}\n`);

  const port = 3456;
  const serverPath = path.resolve(__dirname, '..', 'server.js');

  console.log(`[1/4] Measuring Cold Start in clean isolated process...`);
  const launchStart = performance.now();

  const serverProc: ChildProcess = spawn(process.execPath, [serverPath], {
    env: {
      ...process.env,
      PORT: String(port),
      HOST: '127.0.0.1',
    },
    stdio: ['ignore', 'pipe', 'pipe'],
  });

  let coldStartMs = -1;
  while (performance.now() - launchStart < COLD_START_TIMEOUT_MS) {
    const isUp = await probeHealth(port);
    if (isUp) {
      coldStartMs = performance.now() - launchStart;
      break;
    }
    await sleep(COLD_START_CADENCE_MS);
  }

  if (coldStartMs === -1) {
    console.error(`FAIL: Server did not return 200 on /health within ${COLD_START_TIMEOUT_MS}ms cold start threshold`);
    serverProc.kill('SIGTERM');
    process.exit(1);
  }

  console.log(`Cold Start Latency: ${coldStartMs.toFixed(2)} ms (Threshold: <= ${COLD_START_TIMEOUT_MS} ms)\n`);

  let totalRequestErrors = 0;

  console.log(`[2/4] Running Warm-Up (${WARMUP_REQUESTS_PER_ROUTE} requests per route, 5s timeout)...`);
  for (const routeSpec of ROUTES) {
    let routeWarmupErrors = 0;
    for (let i = 0; i < WARMUP_REQUESTS_PER_ROUTE; i++) {
      const res = await validateSingleRequest(port, routeSpec);
      if (!res.ok) {
        routeWarmupErrors++;
        console.error(`Warm-up error on ${routeSpec.route} (req ${i}): ${res.error}`);
      }
    }
    totalRequestErrors += routeWarmupErrors;
    console.log(`- Warm-up ${routeSpec.route}: completed with ${routeWarmupErrors} errors`);
  }
  console.log('');

  console.log(`[3/4] Running Sustained Window (${SUSTAINED_REQUESTS_PER_ROUTE} reqs @ ${CONCURRENT_CONNECTIONS} conn per route)...`);
  const routeResults: Array<{
    route: string;
    p95Ms: number;
    errors: number;
    throughputReqSec: number;
  }> = [];

  for (const routeSpec of ROUTES) {
    const latencies: number[] = [];
    let validationErrors = 0;

    const result = await autocannon({
      url: `http://127.0.0.1:${port}${routeSpec.route}`,
      connections: CONCURRENT_CONNECTIONS,
      amount: SUSTAINED_REQUESTS_PER_ROUTE,
      timeout: Math.floor(REQUEST_TIMEOUT_MS / 1000),
      setupClient: (client) => {
        client.on('response', (_statusCode, _resBytes, responseTime) => {
          latencies.push(responseTime);
        });
        client.on('headers', (headers) => {
          let contentType = '';
          for (let i = 0; i < headers.headers.length; i += 2) {
            if (headers.headers[i].toLowerCase() === 'content-type') {
              contentType = headers.headers[i + 1];
              break;
            }
          }
          if (
            headers.statusCode !== routeSpec.expectedStatus ||
            !contentType.startsWith(routeSpec.expectedContentType)
          ) {
            validationErrors++;
          }
        });
      },
    });

    latencies.sort((a, b) => a - b);
    const p95Index = Math.floor(latencies.length * 0.95);
    const exactP95 = latencies[p95Index] || result.latency.p97_5 || 0;

    const routeErrors = result.errors + result.timeouts + result.non2xx + validationErrors;
    totalRequestErrors += routeErrors;

    routeResults.push({
      route: routeSpec.route,
      p95Ms: exactP95,
      errors: routeErrors,
      throughputReqSec: result.requests.average || 0,
    });

    console.log(
      `- ${routeSpec.route.padEnd(10)}: p95 = ${exactP95.toFixed(2)} ms | errors = ${routeErrors} | avg req/sec = ${result.requests.average}`
    );
  }

  // Gracefully terminate child process
  serverProc.kill('SIGTERM');

  console.log('\n[4/4] Performance Threshold Verification:');
  let pass = true;

  if (coldStartMs > COLD_START_TIMEOUT_MS) {
    console.error(`FAIL: Cold start ${coldStartMs.toFixed(2)} ms exceeded limit of ${COLD_START_TIMEOUT_MS} ms`);
    pass = false;
  } else {
    console.log(`PASS: Cold start ${coldStartMs.toFixed(2)} ms <= 10,000 ms`);
  }

  for (const r of routeResults) {
    if (r.p95Ms > P95_THRESHOLD_MS) {
      console.error(`FAIL: Route ${r.route} p95 latency ${r.p95Ms.toFixed(2)} ms exceeded limit of ${P95_THRESHOLD_MS} ms`);
      pass = false;
    } else {
      console.log(`PASS: Route ${r.route} p95 latency ${r.p95Ms.toFixed(2)} ms <= ${P95_THRESHOLD_MS} ms`);
    }
  }

  if (totalRequestErrors > 0) {
    console.error(`FAIL: Total request errors ${totalRequestErrors} > 0`);
    pass = false;
  } else {
    console.log(`PASS: Total request errors = 0 across warm-up and sustained windows`);
  }

  if (!pass) {
    console.error('\nOVERALL RESULT: FAIL');
    process.exit(1);
  }

  console.log('\nOVERALL RESULT: PASS');
}

runPerformanceBenchmark().catch((err) => {
  console.error('Unhandled error in performance benchmark:', err);
  process.exit(1);
});

